function mountedSkillStart(MemoryConnection $db):TestResponse{$ability=$db->payload('character:character-player')['abilities'][0];return runCommand($db,'ability.complex',['action'=>'start','requestId'=>'skill-start-'.randomToken(16),'sceneId'=>'scene-one','sourceTokenId'=>'token-player','abilityId'=>$ability['id']]);}
function mountedSkillArguments(MemoryConnection $db,string $action,array $extra=[]):array{$execution=$db->payload('activity')['abilityExecutions'][0];return ['action'=>'command','requestId'=>'skill-command-'.randomToken(16),'executionId'=>$execution['id'],'expectedRevision'=>$execution['revision'],'command'=>['action'=>$action,...$extra]];}
function mountedSkillCommand(MemoryConnection $db,string $action,array $extra=[]):TestResponse{return runCommand($db,'ability.complex',mountedSkillArguments($db,$action,$extra));}

