$db=mountedSkillFixture('body');$mount=$db->payload('token:scene-one:skill-mount');$passenger=$db->payload('token:scene-one:skill-passenger');$r=mountedSkillStart($db);specialCheck($r->status===200,'Mounted body charge starts: '.json_encode($r->body));specialCheck($db->payload('token:scene-one:token-player')['mountedOnTokenId']==='skill-mount','Charge starts mounted');$r=mountedSkillCommand($db,'select-targets',['allocations'=>[['tokenId'=>'token-monster','count'=>1]],'opposed'=>false]);specialCheck($r->status===200,'Select native charge target: '.json_encode($r->body));$r=mountedSkillCommand($db,'plan-charge');specialCheck($r->status===200,'Plan mounted charge: '.json_encode($r->body));$plan=$r->body['execution']['stepStates']['charge-movement'];specialCheck($db->payload('token:scene-one:token-player')['mountedOnTokenId']==='skill-mount'&&empty($plan['sideMoves']),'Charge preview neither dismounts nor pushes mount');specialCheck(array_column($plan['allocations'],'tokenId')===['token-monster'],'Mount and passenger are not phantom charge targets');$r=mountedSkillCommand($db,'confirm-movement',['defenses'=>[['tokenId'=>'token-monster','opposed'=>false]]]);specialCheck($r->status===200,'Confirm charge route: '.json_encode($r->body));specialCheck($db->payload('token:scene-one:token-player')['mountedOnTokenId']==='skill-mount','Confirming preview still does not dismount');$args=mountedSkillArguments($db,'prepare-target',['targetTokenId'=>'token-monster']);$r=runCommand($db,'ability.complex',$args);specialCheck($r->status===200,'First native charge segment: '.json_encode($r->body));$moved=$db->payload('token:scene-one:token-player');specialCheck($moved['x']>20&&!isset($moved['mountedOnTokenId'],$moved['mountedAt']),'Actual charge segment detaches and moves caster');specialCheck($db->payload('token:scene-one:skill-mount')===$mount&&$db->payload('token:scene-one:skill-passenger')===$passenger,'Charge leaves mount and passenger unchanged');$again=runCommand($db,'ability.complex',$args);specialCheck($again->status===200&&!empty($again->body['deduplicated'])&&$db->payload('token:scene-one:token-player')===$moved,'Native charge ACK cannot move twice');
fwrite(STDOUT,json_encode(['ok'=>true,'checks'=>$specialChecks],JSON_UNESCAPED_UNICODE)."\n");
